// ROLES columns (template proof order): head swap7 outer height skip step advance test scale clip scb3 column table cells duff next finish end.
enum {R_HEAD,R_SWAP7,R_OUTER,R_HEIGHT,R_SKIP,R_STEP,R_ADVANCE,R_TEST,R_SCALE,R_CLIP,R_SCB3,R_COLUMN,R_TABLE,R_CELLS,R_DUFF,R_NEXT,R_FINISH,R_END};
